    public LoaiKhuyenMaiDto findLoaiKhuyenMaiById(String maLoaiKhuyenMai) {
        List<LoaiKhuyenMaiDto> types = loadPromotionTypes(SELECT_LOAI_KHUYEN_MAI_BY_ID_SQL, maLoaiKhuyenMai);
