    private List<LoaiKhuyenMaiDto> loadPromotionTypes(String sql, String parameter) {
        Connection connection = null;
        List<LoaiKhuyenMaiDto> types = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                if (parameter != null) {
                    statement.setString(1, parameter);
                }
                try (ResultSet resultSet = statement.executeQuery()) {
                    while (resultSet.next()) {
                        types.add(mapPromotionType(resultSet, ""));
                    }
                }
            }
            return types;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load promotion types.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    private List<KhuyenMaiDto> loadActivePromotions(String sql, Date ngay) {
        Connection connection = null;
        List<KhuyenMaiDto> promotions = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setDate(1, ngay);
                statement.setDate(2, ngay);
                try (ResultSet resultSet = statement.executeQuery()) {
                    while (resultSet.next()) {
                        promotions.add(mapPromotion(resultSet));
                    }
                }
            }
            return promotions;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load active promotions.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    private void bindPromotion(PreparedStatement statement, KhuyenMaiDto khuyenMai) throws SQLException {
        statement.setString(1, khuyenMai.getMaKM());
        statement.setString(2, khuyenMai.getLoaiKM() == null ? null : khuyenMai.getLoaiKM().getMaLoai());
        statement.setString(3, khuyenMai.getTenKM());
        statement.setFloat(4, khuyenMai.getGiaTriKM());
        statement.setDate(5, khuyenMai.getNgayBatDau());
        statement.setDate(6, khuyenMai.getNgayKetThuc());
        statement.setString(7, khuyenMai.getMoTa());
        statement.setDouble(8, khuyenMai.getGiaTriApDung());
    }

    private KhuyenMaiDto mapPromotion(ResultSet resultSet) throws SQLException {
        KhuyenMaiDto promotion = new KhuyenMaiDto();
        promotion.setMaKM(resultSet.getString("MaKM"));
        promotion.setLoaiKM(mapPromotionType(resultSet, "LKM_"));
        promotion.setTenKM(resultSet.getString("TenKM"));
        promotion.setGiaTriKM(resultSet.getFloat("GiaTriKM"));
        promotion.setNgayBatDau(resultSet.getDate("NgayBatDau"));
        promotion.setNgayKetThuc(resultSet.getDate("NgayKetThuc"));
        promotion.setMoTa(resultSet.getString("MoTa"));
        promotion.setNgayTao(resultSet.getTimestamp("NgayTao"));
        promotion.setGiaTriApDung(resultSet.getDouble("GiaTriApDung"));
        return promotion;
    }

    private LoaiKhuyenMaiDto mapPromotionType(ResultSet resultSet, String prefix) throws SQLException {
        String maLoai = resultSet.getString(prefix + "MaLoai");
        if (maLoai == null) {
            return null;
        }
        LoaiKhuyenMaiDto type = new LoaiKhuyenMaiDto();
        type.setMaLoai(maLoai);
        type.setTenLoai(resultSet.getString(prefix + "TenLoai"));
        type.setMoTa(resultSet.getString(prefix + "MoTa"));
        return type;
    }

    private Thuoc_SanPhamDto mapMedicine(ResultSet resultSet, String maThuocColumn) throws SQLException {
        Thuoc_SanPhamDto medicine = new Thuoc_SanPhamDto();
        medicine.setMaThuoc(resultSet.getString(maThuocColumn));
        medicine.setTenThuoc(resultSet.getString("TenThuoc"));
        medicine.setHamLuong(resultSet.getFloat("HamLuong"));
        medicine.setDonViHamLuong(resultSet.getString("DonViHL"));
        medicine.setDuongDung(resultSet.getString("DuongDung"));
        medicine.setQuyCachDongGoi(resultSet.getString("QuyCachDongGoi"));
        medicine.setSDK_GPNK(resultSet.getString("SDK_GPNK"));
        medicine.setHangSX(resultSet.getString("HangSX"));
        medicine.setNuocSX(resultSet.getString("NuocSX"));
        medicine.setHinhAnh(resultSet.getBytes("HinhAnh"));
        medicine.setETC(resultSet.getBoolean("ETC"));
        medicine.setNhomDuocLy(mapNhomDuocLy(resultSet));
        medicine.setLoaiHang(mapLoaiHang(resultSet));
        medicine.setVitri(mapKeHang(resultSet));
        return medicine;
    }

    private NhomDuocLyDto mapNhomDuocLy(ResultSet resultSet) throws SQLException {
        String maNdl = resultSet.getString("NDL_MaNDL");
        if (maNdl == null) {
            return null;
        }
        NhomDuocLyDto nhomDuocLy = new NhomDuocLyDto();
        nhomDuocLy.setMaNDL(maNdl);
        nhomDuocLy.setTenNDL(resultSet.getString("NDL_TenNDL"));
        nhomDuocLy.setMoTa(resultSet.getString("NDL_MoTa"));
        return nhomDuocLy;
    }

    private LoaiHangDto mapLoaiHang(ResultSet resultSet) throws SQLException {
        String maLoaiHang = resultSet.getString("LH_MaLoaiHang");
        if (maLoaiHang == null) {
            return null;
        }
        LoaiHangDto loaiHang = new LoaiHangDto();
        loaiHang.setMaLoaiHang(maLoaiHang);
        loaiHang.setTenLoaiHang(resultSet.getString("LH_TenLH"));
        loaiHang.setMoTa(resultSet.getString("LH_MoTa"));
        return loaiHang;
    }

    private KeHangDto mapKeHang(ResultSet resultSet) throws SQLException {
        String maKe = resultSet.getString("KE_MaKe");
        if (maKe == null) {
            return null;
        }
        KeHangDto keHang = new KeHangDto();
        keHang.setMaKe(maKe);
        keHang.setTenKe(resultSet.getString("KE_TenKe"));
        keHang.setMoTa(resultSet.getString("KE_MoTa"));
        return keHang;
    }

    private void attachUnitDetailsToPromotionMedicines(Collection<Thuoc_SanPhamDto> medicines) {
        if (medicines == null || medicines.isEmpty()) {
            return;
        }

        Map<String, Thuoc_SanPhamDto> medicinesById = new LinkedHashMap<>();
        for (Thuoc_SanPhamDto medicine : medicines) {
            if (medicine != null && medicine.getMaThuoc() != null && !medicine.getMaThuoc().isBlank()) {
                medicinesById.put(medicine.getMaThuoc(), medicine);
            }
        }
        if (medicinesById.isEmpty()) {
            return;
        }

        String sql = """
                SELECT ctdvt.MaThuoc,
                       ctdvt.MaDVT,
                       ctdvt.HeSoQuyDoi,
                       ctdvt.GiaNhap,
                       ctdvt.GiaBan,
                       ctdvt.DonViCoBan,
                       dvt.TenDonViTinh,
                       dvt.KiHieu
                FROM ChiTietDonViTinh ctdvt
                JOIN DonViTinh dvt ON dvt.MaDVT = ctdvt.MaDVT
                WHERE ctdvt.MaThuoc IN (%s)
                ORDER BY ctdvt.MaThuoc ASC, ctdvt.DonViCoBan DESC, ctdvt.HeSoQuyDoi DESC, ctdvt.MaDVT ASC
                """.formatted(placeholders(medicinesById.size()));

        Connection connection = null;
        Map<String, List<ChiTietDonViTinhDto>> detailsByMedicineId = new LinkedHashMap<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                int index = 1;
                for (String maThuoc : medicinesById.keySet()) {
                    statement.setString(index++, maThuoc);
                }
                try (ResultSet resultSet = statement.executeQuery()) {
                    while (resultSet.next()) {
                        String maThuoc = resultSet.getString("MaThuoc");
                        ChiTietDonViTinhDto detail = new ChiTietDonViTinhDto();
                        DonViTinhDto donViTinh = new DonViTinhDto();
                        donViTinh.setMaDVT(resultSet.getString("MaDVT"));
                        donViTinh.setTenDonViTinh(resultSet.getString("TenDonViTinh"));
                        donViTinh.setKiHieu(resultSet.getString("KiHieu"));
                        detail.setDvt(donViTinh);
                        detail.setHeSoQuyDoi(resultSet.getDouble("HeSoQuyDoi"));
                        detail.setGiaNhap(resultSet.getDouble("GiaNhap"));
                        detail.setGiaBan(resultSet.getDouble("GiaBan"));
                        detail.setDonViCoBan(resultSet.getBoolean("DonViCoBan"));
                        detailsByMedicineId.computeIfAbsent(maThuoc, ignored -> new ArrayList<>()).add(detail);
                    }
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load promotion medicine units.", exception);
        } finally {
            closeConnection(connection);
        }

        for (Map.Entry<String, Thuoc_SanPhamDto> entry : medicinesById.entrySet()) {
            Thuoc_SanPhamDto medicine = entry.getValue();
            List<ChiTietDonViTinhDto> details = detailsByMedicineId.getOrDefault(entry.getKey(), new ArrayList<>());
            for (ChiTietDonViTinhDto detail : details) {
                detail.setThuoc(medicine);
            }
            medicine.setDsCTDVT(details);
            medicine.setDvcb(details.stream().filter(ChiTietDonViTinhDto::isDonViCoBan).findFirst().orElse(null));
        }
    }

    private String placeholders(int count) {
        StringJoiner joiner = new StringJoiner(", ");
        for (int i = 0; i < count; i++) {
            joiner.add("?");
        }
        return joiner.toString();
    }
}

package com.example.pharmacy.server.repository.jdbc;

import com.example.pharmacy.common.request.PhieuNhapItemRequest;
import com.example.pharmacy.common.request.PhieuNhapRequest;
import com.example.pharmacy.server.config.JdbcConnectionProvider;
import com.example.pharmacy.server.repository.PurchaseOrderRepository;
import com.example.pharmacy.common.model.ChiTietPhieuNhapDto;
import com.example.pharmacy.common.model.NhaCungCapDto;
import com.example.pharmacy.common.model.NhanVienDto;
import com.example.pharmacy.common.model.PhieuNhapDto;
import com.example.pharmacy.common.model.Thuoc_SanPhamDto;

import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;

public class JdbcPurchaseOrderRepository extends AbstractJdbcRepository implements PurchaseOrderRepository {
    private static final String INSERT_HEADER_SQL = """
            INSERT INTO PhieuNhapDto (MaPN, NgayNhap, TrangThai, GhiChu, MaNCC, MaNV)
            VALUES (?, ?, 1, ?, ?, ?)
            """;
    private static final String INSERT_DETAIL_SQL = """
            INSERT INTO ChiTietPhieuNhapDto (
                MaPN, MaThuoc, MaLH, SoLuong, MaDVT, GiaNhap, ChietKhau, Thue
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """;
    private static final String INSERT_LOT_SQL = """
            INSERT INTO Thuoc_SP_TheoLoDto (
                MaPN, MaThuoc, MaLH, SoLuongTon, SoLuongDat, SoLuongGiu, NSX, HSD
            ) VALUES (?, ?, ?, ?, 0, 0, ?, ?)
            """;
    private static final String UPDATE_PRICING_SQL = """
            UPDATE ChiTietDonViTinhDto
            SET GiaNhap = ?, GiaBan = COALESCE(?, GiaBan)
            WHERE MaThuoc = ? AND MaDVT = ?
            """;
    private static final String SELECT_ALL_SQL = """
            SELECT pn.MaPN,
                   pn.NgayNhap,
                   pn.TrangThai,
                   pn.GhiChu,
                   ncc.MaNCC,
                   ncc.TenNCC,
                   nv.MaNV,
                   nv.TenNV,
                   COALESCE(SUM(
                       (ct.SoLuong * ct.GiaNhap)
                       - ((ct.SoLuong * ct.GiaNhap) * ct.ChietKhau / 100)
                       + (((ct.SoLuong * ct.GiaNhap) - ((ct.SoLuong * ct.GiaNhap) * ct.ChietKhau / 100)) * ct.Thue / 100)
                   ), 0) AS TongTien
            FROM PhieuNhapDto pn
            JOIN NhaCungCapDto ncc ON ncc.MaNCC = pn.MaNCC
            JOIN NhanVienDto nv ON nv.MaNV = pn.MaNV
            LEFT JOIN ChiTietPhieuNhapDto ct ON ct.MaPN = pn.MaPN
            GROUP BY pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu, ncc.MaNCC, ncc.TenNCC, nv.MaNV, nv.TenNV
            ORDER BY pn.NgayNhap DESC, pn.MaPN DESC
            """;
    private static final String SELECT_BY_ID_SQL = """
            SELECT pn.MaPN,
                   pn.NgayNhap,
                   pn.TrangThai,
                   pn.GhiChu,
                   ncc.MaNCC,
                   ncc.TenNCC,
                   nv.MaNV,
                   nv.TenNV,
                   COALESCE(SUM(
                       (ct.SoLuong * ct.GiaNhap)
                       - ((ct.SoLuong * ct.GiaNhap) * ct.ChietKhau / 100)
                       + (((ct.SoLuong * ct.GiaNhap) - ((ct.SoLuong * ct.GiaNhap) * ct.ChietKhau / 100)) * ct.Thue / 100)
                   ), 0) AS TongTien
            FROM PhieuNhapDto pn
            JOIN NhaCungCapDto ncc ON ncc.MaNCC = pn.MaNCC
            JOIN NhanVienDto nv ON nv.MaNV = pn.MaNV
            LEFT JOIN ChiTietPhieuNhapDto ct ON ct.MaPN = pn.MaPN
            WHERE pn.MaPN = ?
            GROUP BY pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu, ncc.MaNCC, ncc.TenNCC, nv.MaNV, nv.TenNV
            """;
    private static final String SELECT_DETAILS_SQL = """
            SELECT ct.MaPN,
                   ct.MaThuoc,
                   ct.MaLH,
                   ct.SoLuong,
                   ct.GiaNhap,
                   ct.ChietKhau,
                   ct.Thue,
                   ts.TenThuoc
            FROM ChiTietPhieuNhapDto ct
            JOIN Thuoc_SanPhamDto ts ON ts.MaThuoc = ct.MaThuoc
            WHERE ct.MaPN = ?
            ORDER BY ct.MaLH ASC, ct.MaThuoc ASC
            """;

    public JdbcPurchaseOrderRepository(JdbcConnectionProvider connectionProvider) {
        super(connectionProvider);
    }

    @Override
    public void insertHeader(String maPhieuNhap, String employeeId, PhieuNhapRequest request) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_HEADER_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setDate(2, Date.valueOf(request.getNgayNhap()));
                statement.setString(3, request.getGhiChu());
                statement.setString(4, request.getMaNhaCungCap());
                statement.setString(5, employeeId);
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order header.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void insertDetail(String maPhieuNhap, String maLo, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_DETAIL_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setString(2, item.getMaThuoc());
                statement.setString(3, maLo);
                statement.setInt(4, item.getSoLuong());
                statement.setString(5, item.getMaDvt());
                statement.setBigDecimal(6, item.getGiaNhap());
                statement.setBigDecimal(7, item.getChietKhau());
                statement.setBigDecimal(8, item.getThue());
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order detail.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void insertLot(String maPhieuNhap, String maLo, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_LOT_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setString(2, item.getMaThuoc());
                statement.setString(3, maLo);
                statement.setInt(4, item.getSoLuong());
                statement.setDate(5, item.getNsx() == null ? null : Date.valueOf(item.getNsx()));
                statement.setDate(6, item.getHsd() == null ? null : Date.valueOf(item.getHsd()));
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order lot.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void updatePricing(String maThuoc, String maDvt, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(UPDATE_PRICING_SQL)) {
                statement.setBigDecimal(1, item.getGiaNhap());
                statement.setBigDecimal(2, item.getGiaBanCapNhat());
                statement.setString(3, maThuoc);
                statement.setString(4, maDvt);
                int updated = statement.executeUpdate();
                if (updated == 0) {
                    throw new IllegalStateException("No ChiTietDonViTinhDto row found for " + maThuoc + " / " + maDvt);
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not update medicine pricing after import.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<PhieuNhapDto> findAll() {
        Connection connection = null;
        List<PhieuNhapDto> list = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_ALL_SQL);
                 ResultSet resultSet = statement.executeQuery()) {
                while (resultSet.next()) {
                    list.add(mapHeader(resultSet));
                }
            }
            return list;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase orders.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public PhieuNhapDto findById(String maPhieuNhap) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_BY_ID_SQL)) {
                statement.setString(1, maPhieuNhap);
                try (ResultSet resultSet = statement.executeQuery()) {
                    if (resultSet.next()) {
                        return mapHeader(resultSet);
                    }
                    return null;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase order " + maPhieuNhap, exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<ChiTietPhieuNhapDto> findDetailsByMaPhieuNhap(String maPhieuNhap) {
        Connection connection = null;
        List<ChiTietPhieuNhapDto> list = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_DETAILS_SQL)) {
                statement.setString(1, maPhieuNhap);
                try (ResultSet resultSet = statement.executeQuery()) {
                    while (resultSet.next()) {
                        list.add(mapDetail(resultSet));
                    }
                }
            }
            return list;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase order details for " + maPhieuNhap, exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public long findMaxLotNumber() {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(
                    "SELECT COALESCE(MAX(CAST(SUBSTRING(MaLH, 3) AS UNSIGNED)), 0) FROM Thuoc_SP_TheoLoDto WHERE MaLH REGEXP '^LH[0-9]+$'")) {
                try (ResultSet resultSet = statement.executeQuery()) {
                    return resultSet.next() ? resultSet.getLong(1) : 0;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not find max lot number.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    private PhieuNhapDto mapHeader(ResultSet resultSet) throws Exception {
        PhieuNhapDto phieuNhap = new PhieuNhapDto();
        phieuNhap.setMaPN(resultSet.getString("MaPN"));
        Date ngayNhap = resultSet.getDate("NgayNhap");
        phieuNhap.setNgayNhap(ngayNhap == null ? null : ngayNhap.toLocalDate());
        phieuNhap.setTrangThai(resultSet.getBoolean("TrangThai"));
        phieuNhap.setGhiChu(resultSet.getString("GhiChu"));
        phieuNhap.setTongTien(resultSet.getDouble("TongTien"));

        NhaCungCapDto nhaCungCap = new NhaCungCapDto();
        nhaCungCap.setMaNCC(resultSet.getString("MaNCC"));
        nhaCungCap.setTenNCC(resultSet.getString("TenNCC"));
        phieuNhap.setNhaCungCap(nhaCungCap);

        NhanVienDto nhanVien = new NhanVienDto();
        nhanVien.setMaNV(resultSet.getString("MaNV"));
        nhanVien.setTenNV(resultSet.getString("TenNV"));
        phieuNhap.setNhanVien(nhanVien);
        return phieuNhap;
    }

    private ChiTietPhieuNhapDto mapDetail(ResultSet resultSet) throws Exception {
        ChiTietPhieuNhapDto detail = new ChiTietPhieuNhapDto();
        PhieuNhapDto phieuNhap = new PhieuNhapDto();
        phieuNhap.setMaPN(resultSet.getString("MaPN"));
        detail.setPhieuNhap(phieuNhap);

        Thuoc_SanPhamDto thuoc = new Thuoc_SanPhamDto();
        thuoc.setMaThuoc(resultSet.getString("MaThuoc"));
        thuoc.setTenThuoc(resultSet.getString("TenThuoc"));
        detail.setThuoc(thuoc);

        detail.setMaLH(resultSet.getString("MaLH"));
        detail.setSoLuong(resultSet.getInt("SoLuong"));
        detail.setGiaNhap(resultSet.getDouble("GiaNhap"));
        detail.setChietKhau(resultSet.getFloat("ChietKhau"));
        detail.setThue(resultSet.getFloat("Thue"));
        return detail;
    }
}

package com.example.pharmacy.server.repository.jdbc;

import com.example.pharmacy.common.request.PhieuNhapItemRequest;
import com.example.pharmacy.common.request.PhieuNhapRequest;
import com.example.pharmacy.server.config.JdbcConnectionProvider;
import com.example.pharmacy.server.repository.PurchaseOrderRepository;
import com.example.pharmacy.common.model.ChiTietPhieuNhapDto;
import com.example.pharmacy.common.model.NhaCungCapDto;
import com.example.pharmacy.common.model.NhanVienDto;
import com.example.pharmacy.common.model.PhieuNhapDto;
import com.example.pharmacy.common.model.Thuoc_SanPhamDto;

import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.ArrayList;
import java.util.List;

public class JdbcPurchaseOrderRepository extends AbstractJdbcRepository implements PurchaseOrderRepository {
    private static final String INSERT_PHIEU_NHAP_SQL = """
            INSERT INTO PhieuNhap (MaPN, NgayNhap, TrangThai, GhiChu, MaNCC, MaNV)
            VALUES (?, ?, ?, ?, ?, ?)
            """;
    private static final String INSERT_CHI_TIET_PHIEU_NHAP_SQL = """
            INSERT INTO ChiTietPhieuNhap (
                MaPN, MaThuoc, MaLH, SoLuong, MaDVT, GiaNhap, ChietKhau, Thue
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """;
    private static final String INSERT_LOT_SQL = """
            INSERT INTO Thuoc_SP_TheoLo (
                MaPN, MaThuoc, MaLH, SoLuongTon, SoLuongDat, SoLuongGiu, NSX, HSD
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """;
    private static final String UPDATE_UNIT_PRICE_SQL = """
            UPDATE ChiTietDonViTinh
            SET GiaNhap = ?, GiaBan = ?
            WHERE MaThuoc = ? AND MaDVT = ?
            """;
    private static final String SELECT_ALL_PHIEU_NHAP_SQL = """
            SELECT pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu,
                   ncc.MaNCC, ncc.TenNCC,
                   nv.MaNV, nv.TenNV,
                   COUNT(ct.MaPN) AS soDong
            FROM PhieuNhap pn
            JOIN NhaCungCap ncc ON ncc.MaNCC = pn.MaNCC
            JOIN NhanVien nv ON nv.MaNV = pn.MaNV
            LEFT JOIN ChiTietPhieuNhap ct ON ct.MaPN = pn.MaPN
            GROUP BY pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu, ncc.MaNCC, ncc.TenNCC, nv.MaNV, nv.TenNV
            ORDER BY pn.NgayNhap DESC, pn.MaPN DESC
            """;
    private static final String SELECT_PHIEU_NHAP_BY_ID_SQL = """
            SELECT pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu,
                   ncc.MaNCC, ncc.TenNCC,
                   nv.MaNV, nv.TenNV,
                   COUNT(ct.MaPN) AS soDong
            FROM PhieuNhap pn
            JOIN NhaCungCap ncc ON ncc.MaNCC = pn.MaNCC
            JOIN NhanVien nv ON nv.MaNV = pn.MaNV
            LEFT JOIN ChiTietPhieuNhap ct ON ct.MaPN = pn.MaPN
            WHERE pn.MaPN = ?
            GROUP BY pn.MaPN, pn.NgayNhap, pn.TrangThai, pn.GhiChu, ncc.MaNCC, ncc.TenNCC, nv.MaNV, nv.TenNV
            """;
    private static final String SELECT_CHI_TIET_PHIEU_NHAP_SQL = """
            SELECT ct.MaPN, ct.MaThuoc, ct.MaLH, ct.SoLuong, ct.MaDVT, ct.GiaNhap, ct.ChietKhau, ct.Thue,
                   ts.TenThuoc
            FROM ChiTietPhieuNhap ct
            JOIN Thuoc_SanPham ts ON ts.MaThuoc = ct.MaThuoc
            WHERE ct.MaPN = ?
            ORDER BY ts.TenThuoc ASC
            """;
    private static final String SELECT_UNIT_PRICE_SQL = """
            SELECT GiaNhap, GiaBan
            FROM ChiTietDonViTinh
            WHERE MaThuoc = ? AND MaDVT = ?
            """;
    private static final String INSERT_DEFAULT_UNIT_SQL = """
            INSERT INTO ChiTietDonViTinh (MaThuoc, MaDVT, HeSoQuyDoi, GiaNhap, GiaBan, DonViCoBan)
            SELECT ?, MaDVT, 1.0, 0.0, 0.0, 1
            FROM DonViTinh
            WHERE MaDVT = ?
            """;

    public JdbcPurchaseOrderRepository(JdbcConnectionProvider connectionProvider) {
        super(connectionProvider);
    }

    @Override
    public void insertHeader(String maPhieuNhap, String employeeId, PhieuNhapRequest request) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_PHIEU_NHAP_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setDate(2, Date.valueOf(request.getNgayNhap()));
                statement.setString(3, request.getGhiChu());
                statement.setString(4, request.getMaNhaCungCap());
                statement.setString(5, employeeId);
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order header.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void insertDetail(String maPhieuNhap, String maLo, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_CHI_TIET_PHIEU_NHAP_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setString(2, item.getMaThuoc());
                statement.setString(3, maLo);
                statement.setInt(4, item.getSoLuong());
                statement.setString(5, item.getMaDvt());
                statement.setBigDecimal(6, item.getGiaNhap());
                statement.setBigDecimal(7, item.getChietKhau());
                statement.setBigDecimal(8, item.getThue());
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order detail.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void insertLot(String maPhieuNhap, String maLo, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_LOT_SQL)) {
                statement.setString(1, maPhieuNhap);
                statement.setString(2, item.getMaThuoc());
                statement.setString(3, maLo);
                statement.setInt(4, item.getSoLuong());
                statement.setDate(5, item.getNsx() == null ? null : Date.valueOf(item.getNsx()));
                statement.setDate(6, item.getHsd() == null ? null : Date.valueOf(item.getHsd()));
                statement.executeUpdate();
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not insert purchase order lot.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public void updatePricing(String maThuoc, String maDvt, PhieuNhapItemRequest item) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(UPDATE_UNIT_PRICE_SQL)) {
                statement.setBigDecimal(1, item.getGiaNhap());
                statement.setBigDecimal(2, item.getGiaBanCapNhat());
                statement.setString(3, maThuoc);
                statement.setString(4, maDvt);
                int updated = statement.executeUpdate();
                if (updated == 0) {
                    throw new IllegalStateException("No ChiTietDonViTinh row found for " + maThuoc + " / " + maDvt);
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not update medicine pricing after import.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<PhieuNhapDto> findAll() {
        Connection connection = null;
        List<PhieuNhapDto> list = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_ALL_PHIEU_NHAP_SQL);
                 ResultSet resultSet = statement.executeQuery()) {
                while (resultSet.next()) {
                    list.add(mapHeader(resultSet));
                }
            }
            return list;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase orders.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public PhieuNhapDto findById(String maPhieuNhap) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_PHIEU_NHAP_BY_ID_SQL)) {
                statement.setString(1, maPhieuNhap);
                try (ResultSet resultSet = statement.executeQuery()) {
                    if (resultSet.next()) {
                        return mapHeader(resultSet);
                    }
                    return null;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase order " + maPhieuNhap, exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<ChiTietPhieuNhapDto> findDetailsByMaPhieuNhap(String maPhieuNhap) {
        Connection connection = null;
        List<ChiTietPhieuNhapDto> list = new ArrayList<>();
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(SELECT_CHI_TIET_PHIEU_NHAP_SQL)) {
                statement.setString(1, maPhieuNhap);
                try (ResultSet resultSet = statement.executeQuery()) {
                    while (resultSet.next()) {
                        list.add(mapDetail(resultSet));
                    }
                }
            }
            return list;
        } catch (Exception exception) {
            throw new IllegalStateException("Could not load purchase order details for " + maPhieuNhap, exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public long findMaxLotNumber() {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(
                    "SELECT COALESCE(MAX(CAST(SUBSTRING(MaLH, 3) AS UNSIGNED)), 0) FROM Thuoc_SP_TheoLo WHERE MaLH REGEXP '^LH[0-9]+$'")) {
                try (ResultSet resultSet = statement.executeQuery()) {
                    return resultSet.next() ? resultSet.getLong(1) : 0;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not find max lot number.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    private PhieuNhapDto mapHeader(ResultSet resultSet) throws Exception {
        PhieuNhapDto phieuNhap = new PhieuNhapDto();
        phieuNhap.setMaPN(resultSet.getString("MaPN"));
        Date ngayNhap = resultSet.getDate("NgayNhap");
        phieuNhap.setNgayNhap(ngayNhap == null ? null : ngayNhap.toLocalDate());
        phieuNhap.setTrangThai(resultSet.getBoolean("TrangThai"));
        phieuNhap.setGhiChu(resultSet.getString("GhiChu"));
        phieuNhap.setTongTien(resultSet.getDouble("TongTien"));

        NhaCungCapDto nhaCungCap = new NhaCungCapDto();
        nhaCungCap.setMaNCC(resultSet.getString("MaNCC"));
        nhaCungCap.setTenNCC(resultSet.getString("TenNCC"));
        phieuNhap.setNhaCungCap(nhaCungCap);

        NhanVienDto nhanVien = new NhanVienDto();
        nhanVien.setMaNV(resultSet.getString("MaNV"));
        nhanVien.setTenNV(resultSet.getString("TenNV"));
        phieuNhap.setNhanVien(nhanVien);
        return phieuNhap;
    }

    private ChiTietPhieuNhapDto mapDetail(ResultSet resultSet) throws Exception {
        ChiTietPhieuNhapDto detail = new ChiTietPhieuNhapDto();
        PhieuNhapDto phieuNhap = new PhieuNhapDto();
        phieuNhap.setMaPN(resultSet.getString("MaPN"));
        detail.setPhieuNhap(phieuNhap);

        Thuoc_SanPhamDto thuoc = new Thuoc_SanPhamDto();
        thuoc.setMaThuoc(resultSet.getString("MaThuoc"));
        thuoc.setTenThuoc(resultSet.getString("TenThuoc"));
        detail.setThuoc(thuoc);

        detail.setMaLH(resultSet.getString("MaLH"));
        detail.setSoLuong(resultSet.getInt("SoLuong"));
        detail.setGiaNhap(resultSet.getDouble("GiaNhap"));
        detail.setChietKhau(resultSet.getFloat("ChietKhau"));
        detail.setThue(resultSet.getFloat("Thue"));
        return detail;
    }
}

package com.example.pharmacy.server.repository.jdbc;

import com.example.pharmacy.common.dto.ExpiringLotDTO;
import com.example.pharmacy.common.dto.RevenuePointDTO;
import com.example.pharmacy.common.dto.TopSellingProductDTO;
import com.example.pharmacy.common.request.DateRangeRequest;
import com.example.pharmacy.server.config.JdbcConnectionProvider;
import com.example.pharmacy.server.repository.ReportRepository;
import com.example.pharmacy.common.model.HoaDonDisplayDto;
import com.example.pharmacy.common.model.ThongKeBanHangDto;
import com.example.pharmacy.common.model.ThongKeTonKhoDto;
import com.example.pharmacy.common.model.ThongKeTopSanPhamDto;
import com.example.pharmacy.common.model.ThuocHetHanDto;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class JdbcReportRepository extends AbstractJdbcRepository implements ReportRepository {
    private static final String REVENUE_BY_RANGE_SQL = """
            SELECT DATE(hd.NgayLap) AS bucket_date,
                   ROUND(SUM((cthd.SoLuong * cthd.DonGia) - cthd.GiamGia), 2) AS revenue
            FROM HoaDonDto hd
            JOIN ChiTietHoaDonDto cthd ON cthd.MaHD = hd.MaHD
            WHERE DATE(hd.NgayLap) BETWEEN ? AND ?
            GROUP BY DATE(hd.NgayLap)
            ORDER BY DATE(hd.NgayLap)
            """;
    private static final String TOP_SELLING_BY_RANGE_SQL = """
            SELECT ts.MaThuoc,
                   ts.TenThuoc,
                   SUM(cthd.SoLuong) AS quantity_sold,
                   ROUND(SUM((cthd.SoLuong * cthd.DonGia) - cthd.GiamGia), 2) AS revenue
            FROM HoaDonDto hd
            JOIN ChiTietHoaDonDto cthd ON cthd.MaHD = hd.MaHD
            JOIN Thuoc_SP_TheoLoDto lo ON lo.MaLH = cthd.MaLH
            JOIN Thuoc_SanPhamDto ts ON ts.MaThuoc = lo.MaThuoc
            WHERE DATE(hd.NgayLap) BETWEEN ? AND ?
            GROUP BY ts.MaThuoc, ts.TenThuoc
            ORDER BY quantity_sold DESC, revenue DESC
            LIMIT ?
            """;
    private static final String EXPIRED_LOTS_SQL = """
            SELECT lo.MaLH,
                   lo.MaThuoc,
                   ts.TenThuoc,
                   lo.HSD,
                   lo.SoLuongTon,
                   DATEDIFF(lo.HSD, CURRENT_DATE()) AS days_to_expiry
            FROM Thuoc_SP_TheoLoDto lo
            JOIN Thuoc_SanPhamDto ts ON ts.MaThuoc = lo.MaThuoc
            WHERE lo.SoLuongTon > 0
              AND lo.HSD IS NOT NULL
              AND lo.HSD < CURRENT_DATE()
            ORDER BY lo.HSD ASC, lo.MaLH ASC
            """;
    private static final String EXPIRING_LOTS_SQL = """
            SELECT lo.MaLH,
                   lo.MaThuoc,
                   ts.TenThuoc,
                   lo.HSD,
                   lo.SoLuongTon,
                   DATEDIFF(lo.HSD, CURRENT_DATE()) AS days_to_expiry
            FROM Thuoc_SP_TheoLoDto lo
            JOIN Thuoc_SanPhamDto ts ON ts.MaThuoc = lo.MaThuoc
            WHERE lo.SoLuongTon > 0
              AND lo.HSD IS NOT NULL
              AND lo.HSD BETWEEN CURRENT_DATE() AND DATE_ADD(CURRENT_DATE(), INTERVAL ? DAY)
            ORDER BY lo.HSD ASC, lo.MaLH ASC
            """;
    private static final String HOA_DON_BY_RANGE_SQL = """
            SELECT
                h.MaHD,
                DATE(h.NgayLap) AS ngayLap,
                h.MaKH,
                h.MaNV,
                COALESCE(SUM(ct.SoLuong * (ct.DonGia - ct.GiamGia)), 0) * 1.05 AS tongTienNet
            FROM HoaDonDto h
            LEFT JOIN ChiTietHoaDonDto ct ON h.MaHD = ct.MaHD
            WHERE DATE(h.NgayLap) BETWEEN ? AND ?
            GROUP BY h.MaHD, DATE(h.NgayLap), h.MaKH, h.MaNV
            ORDER BY ngayLap DESC, h.MaHD DESC
            """;
    private static final String TOP_BAN_CHAY_SQL = """
            SELECT
                t.MaThuoc,
                t.TenThuoc,
                COALESCE(dvtChuan.KiHieu, dvtChuan.TenDonViTinh, 'N/A') AS DVT_CoBan,
                CAST(SUM(cthd.SoLuong * COALESCE(ctdvtBan.HeSoQuyDoi, 1)) AS SIGNED) AS TongSoLuong,
                ROUND(SUM(cthd.SoLuong * (cthd.DonGia - cthd.GiamGia)), 2) AS TongDoanhThu
            FROM ChiTietHoaDonDto cthd
            JOIN HoaDonDto hd ON cthd.MaHD = hd.MaHD
            JOIN Thuoc_SP_TheoLoDto lo ON cthd.MaLH = lo.MaLH
            JOIN Thuoc_SanPhamDto t ON lo.MaThuoc = t.MaThuoc
            LEFT JOIN ChiTietDonViTinhDto ctdvtChuan
                ON t.MaThuoc = ctdvtChuan.MaThuoc
               AND ctdvtChuan.DonViCoBan = 1
            LEFT JOIN DonViTinhDto dvtChuan
                ON ctdvtChuan.MaDVT = dvtChuan.MaDVT
            LEFT JOIN ChiTietDonViTinhDto ctdvtBan
                ON t.MaThuoc = ctdvtBan.MaThuoc
               AND cthd.MaDVT = ctdvtBan.MaDVT
            WHERE DATE(hd.NgayLap) BETWEEN ? AND ?
            GROUP BY t.MaThuoc, t.TenThuoc, COALESCE(dvtChuan.KiHieu, dvtChuan.TenDonViTinh, 'N/A')
            ORDER BY TongSoLuong DESC, TongDoanhThu DESC
            LIMIT ?
            """;
    private static final String TOP_DOANH_THU_SQL = """
            SELECT
                t.MaThuoc,
                t.TenThuoc,
                COALESCE(dvtChuan.KiHieu, dvtChuan.TenDonViTinh, 'N/A') AS DVT_CoBan,
                CAST(SUM(cthd.SoLuong * COALESCE(ctdvtBan.HeSoQuyDoi, 1)) AS SIGNED) AS TongSoLuong,
                ROUND(SUM(cthd.SoLuong * (cthd.DonGia - cthd.GiamGia)), 2) AS TongDoanhThu
            FROM ChiTietHoaDonDto cthd
            JOIN HoaDonDto hd ON cthd.MaHD = hd.MaHD
            JOIN Thuoc_SP_TheoLoDto lo ON cthd.MaLH = lo.MaLH
            JOIN Thuoc_SanPhamDto t ON lo.MaThuoc = t.MaThuoc
            LEFT JOIN ChiTietDonViTinhDto ctdvtChuan
                ON t.MaThuoc = ctdvtChuan.MaThuoc
               AND ctdvtChuan.DonViCoBan = 1
            LEFT JOIN DonViTinhDto dvtChuan
                ON ctdvtChuan.MaDVT = dvtChuan.MaDVT
            LEFT JOIN ChiTietDonViTinhDto ctdvtBan
                ON t.MaThuoc = ctdvtBan.MaThuoc
               AND cthd.MaDVT = ctdvtBan.MaDVT
            WHERE DATE(hd.NgayLap) BETWEEN ? AND ?
            GROUP BY t.MaThuoc, t.TenThuoc, COALESCE(dvtChuan.KiHieu, dvtChuan.TenDonViTinh, 'N/A')
            ORDER BY TongDoanhThu DESC, TongSoLuong DESC
            LIMIT ?
            """;
    private static final String THUOC_HET_HAN_SQL = """
            SELECT
                t.MaThuoc AS maThuocHH,
                t.TenThuoc AS tenThuocHH,
                SUM(l.SoLuongTon) AS soLuong,
                l.HSD AS ngayHetHan
            FROM Thuoc_SP_TheoLoDto l
            JOIN Thuoc_SanPhamDto t ON l.MaThuoc = t.MaThuoc
            WHERE l.SoLuongTon > 0
              AND l.HSD IS NOT NULL
              AND l.HSD <= DATE_ADD(
                    CURRENT_DATE(),
                    INTERVAL COALESCE((
                        SELECT CASE
                            WHEN TRIM(GiaTri) REGEXP '^[0-9]+$' THEN CAST(TRIM(GiaTri) AS SIGNED)
                            ELSE NULL
                        END
                        FROM ThongSoUngDung
                        WHERE TenThongSo = 'NgayHetHan'
                        LIMIT 1
                    ), 30) DAY
                )
            GROUP BY t.MaThuoc, t.TenThuoc, l.HSD
            ORDER BY l.HSD ASC, t.MaThuoc ASC
            """;
    private static final String THONG_KE_XNT_SQL = """
            WITH DonViCoBan AS (
                SELECT
                    MaThuoc,
                    MaDVT,
                    COALESCE(HeSoQuyDoi, 1) AS HeSoQuyDoi
                FROM ChiTietDonViTinhDto
                WHERE DonViCoBan = 1
            ),
            BaseUnits AS (
                SELECT
                    ct.MaThuoc,
                    dvt.KiHieu AS DVT
                FROM ChiTietDonViTinhDto ct
                JOIN DonViTinhDto dvt ON ct.MaDVT = dvt.MaDVT
                WHERE ct.DonViCoBan = 1
            ),
            AllProducts AS (
                SELECT
                    t.MaThuoc,
                    t.TenThuoc,
                    COALESCE(bu.DVT, 'N/A') AS DVT
                FROM Thuoc_SanPhamDto t
                LEFT JOIN BaseUnits bu ON t.MaThuoc = bu.MaThuoc
            ),
            Transactions AS (
                SELECT
                    ctpn.MaThuoc,
                    pn.NgayNhap AS NgayGiaoDich,
                    CEIL(ctpn.SoLuong * COALESCE(dvt.HeSoQuyDoi, 1) / dvtcb.HeSoQuyDoi) AS SoLuongNhap,
                    0 AS SoLuongXuat
                FROM ChiTietPhieuNhapDto ctpn
                JOIN PhieuNhapDto pn ON ctpn.MaPN = pn.MaPN
                LEFT JOIN ChiTietDonViTinhDto dvt
                    ON ctpn.MaThuoc = dvt.MaThuoc
                   AND ctpn.MaDVT = dvt.MaDVT
                JOIN DonViCoBan dvtcb ON ctpn.MaThuoc = dvtcb.MaThuoc

                UNION ALL

                SELECT
                    lo.MaThuoc,
                    pt.NgayLap AS NgayGiaoDich,
                    CEIL(ctpt.SoLuong * COALESCE(dvt.HeSoQuyDoi, 1) / dvtcb.HeSoQuyDoi) AS SoLuongNhap,
                    0 AS SoLuongXuat
                FROM ChiTietPhieuTraHangDto ctpt
                JOIN PhieuTraHangDto pt ON ctpt.MaPT = pt.MaPT
                JOIN Thuoc_SP_TheoLoDto lo ON ctpt.MaLH = lo.MaLH
                LEFT JOIN ChiTietDonViTinhDto dvt
                    ON lo.MaThuoc = dvt.MaThuoc
                   AND ctpt.MaDVT = dvt.MaDVT
                JOIN DonViCoBan dvtcb ON lo.MaThuoc = dvtcb.MaThuoc

                UNION ALL

                SELECT
                    ctpd.MaThuoc,
                    pd.NgayLap AS NgayGiaoDich,
                    CEIL(ABS(ctpd.SoLuong) * COALESCE(dvt.HeSoQuyDoi, 1) / dvtcb.HeSoQuyDoi) AS SoLuongNhap,
                    0 AS SoLuongXuat
                FROM ChiTietPhieuDoiHangDto ctpd
                JOIN PhieuDoiHangDto pd ON ctpd.MaPD = pd.MaPD
                LEFT JOIN ChiTietDonViTinhDto dvt
                    ON ctpd.MaThuoc = dvt.MaThuoc
                   AND ctpd.MaDVT = dvt.MaDVT
                JOIN DonViCoBan dvtcb ON ctpd.MaThuoc = dvtcb.MaThuoc
                WHERE ctpd.SoLuong < 0

                UNION ALL

                SELECT
                    lo.MaThuoc,
                    hd.NgayLap AS NgayGiaoDich,
                    0 AS SoLuongNhap,
                    CEIL(cthd.SoLuong * COALESCE(dvt.HeSoQuyDoi, 1) / dvtcb.HeSoQuyDoi) AS SoLuongXuat
                FROM ChiTietHoaDonDto cthd
                JOIN HoaDonDto hd ON cthd.MaHD = hd.MaHD
                JOIN Thuoc_SP_TheoLoDto lo ON cthd.MaLH = lo.MaLH
                LEFT JOIN ChiTietDonViTinhDto dvt
                    ON lo.MaThuoc = dvt.MaThuoc
                   AND cthd.MaDVT = dvt.MaDVT
                JOIN DonViCoBan dvtcb ON lo.MaThuoc = dvtcb.MaThuoc

                UNION ALL

                SELECT
                    ctpd.MaThuoc,
                    pd.NgayLap AS NgayGiaoDich,
                    0 AS SoLuongNhap,
                    CEIL(ctpd.SoLuong * COALESCE(dvt.HeSoQuyDoi, 1) / dvtcb.HeSoQuyDoi) AS SoLuongXuat
                FROM ChiTietPhieuDoiHangDto ctpd
                JOIN PhieuDoiHangDto pd ON ctpd.MaPD = pd.MaPD
                LEFT JOIN ChiTietDonViTinhDto dvt
                    ON ctpd.MaThuoc = dvt.MaThuoc
                   AND ctpd.MaDVT = dvt.MaDVT
                JOIN DonViCoBan dvtcb ON ctpd.MaThuoc = dvtcb.MaThuoc
                WHERE ctpd.SoLuong > 0
            ),
            DailySummary AS (
                SELECT
                    MaThuoc,
                    DATE(NgayGiaoDich) AS Ngay,
                    SUM(SoLuongNhap) AS TongNhap,
                    SUM(SoLuongXuat) AS TongXuat
                FROM Transactions
                GROUP BY MaThuoc, DATE(NgayGiaoDich)
            )
            SELECT
                p.MaThuoc,
                p.TenThuoc,
                p.DVT,
                COALESCE(SUM(CASE WHEN ds.Ngay < ? THEN ds.TongNhap - ds.TongXuat ELSE 0 END), 0) AS TonDauKy,
                COALESCE(SUM(CASE WHEN ds.Ngay BETWEEN ? AND ? THEN ds.TongNhap ELSE 0 END), 0) AS NhapTrongKy,
                COALESCE(SUM(CASE WHEN ds.Ngay BETWEEN ? AND ? THEN ds.TongXuat ELSE 0 END), 0) AS XuatTrongKy,
                COALESCE(SUM(CASE WHEN ds.Ngay <= ? THEN ds.TongNhap - ds.TongXuat ELSE 0 END), 0) AS TonCuoiKy
            FROM AllProducts p
            LEFT JOIN DailySummary ds ON p.MaThuoc = ds.MaThuoc
            GROUP BY p.MaThuoc, p.TenThuoc, p.DVT
            HAVING
                COALESCE(SUM(CASE WHEN ds.Ngay <= ? THEN ds.TongNhap - ds.TongXuat ELSE 0 END), 0) <> 0
                OR COALESCE(SUM(CASE WHEN ds.Ngay BETWEEN ? AND ? THEN ds.TongNhap ELSE 0 END), 0) <> 0
                OR COALESCE(SUM(CASE WHEN ds.Ngay BETWEEN ? AND ? THEN ds.TongXuat ELSE 0 END), 0) <> 0
            ORDER BY p.TenThuoc
            """;

    public JdbcReportRepository(JdbcConnectionProvider connectionProvider) {
        super(connectionProvider);
    }

    @Override
    public List<ThongKeBanHangDto> findThongKeBanHangByDateRange(DateRangeRequest request, ReportBucket bucket) {
        Connection connection = null;
        try {
            connection = getConnection();
            String sql = buildThongKeBanHangSql(bucket);
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                bindDateRangeTwice(statement, request);
                try (ResultSet resultSet = statement.executeQuery()) {
                    List<ThongKeBanHangDto> results = new ArrayList<>();
                    while (resultSet.next()) {
                        results.add(new ThongKeBanHangDto(
                                resultSet.getString("ThoiGian"),
                                resultSet.getInt("SoLuongHoaDon"),
                                resultSet.getDouble("TongGiaTri"),
                                resultSet.getDouble("GiamGia"),
                                resultSet.getInt("SoLuongDonTra"),
                                resultSet.getDouble("GiaTriDonTra"),
                                resultSet.getDouble("DoanhThu")
                        ));
                    }
                    return results;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not query sales summary report.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<HoaDonDisplayDto> findHoaDonByDateRange(DateRangeRequest request) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(HOA_DON_BY_RANGE_SQL)) {
                statement.setDate(1, Date.valueOf(request.getFromDate()));
                statement.setDate(2, Date.valueOf(request.getToDate()));
                try (ResultSet resultSet = statement.executeQuery()) {
                    List<HoaDonDisplayDto> results = new ArrayList<>();
                    while (resultSet.next()) {
                        results.add(new HoaDonDisplayDto(
                                resultSet.getString("MaHD"),
                                resultSet.getObject("ngayLap", LocalDate.class),
                                resultSet.getString("MaKH"),
                                resultSet.getString("MaNV"),
                                resultSet.getDouble("tongTienNet")
                        ));
                    }
                    return results;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not query invoice list for report.", exception);
        } finally {
            closeConnection(connection);
        }
    }

    @Override
    public List<ThongKeTopSanPhamDto> findTopBanChayByDateRange(DateRangeRequest request, int limit) {
        return queryTopProducts(TOP_BAN_CHAY_SQL, request, limit);
    }

    @Override
    public List<ThongKeTopSanPhamDto> findTopDoanhThuByDateRange(DateRangeRequest request, int limit) {
        return queryTopProducts(TOP_DOANH_THU_SQL, request, limit);
    }

    @Override
    public List<ThongKeTonKhoDto> findThongKeXnt(DateRangeRequest request) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(THONG_KE_XNT_SQL)) {
                LocalDate fromDate = request.getFromDate();
                LocalDate toDate = request.getToDate();
                statement.setDate(1, Date.valueOf(fromDate));
                statement.setDate(2, Date.valueOf(fromDate));
                statement.setDate(3, Date.valueOf(toDate));
                statement.setDate(4, Date.valueOf(fromDate));
                statement.setDate(5, Date.valueOf(toDate));
                statement.setDate(6, Date.valueOf(toDate));
                statement.setDate(7, Date.valueOf(toDate));
                statement.setDate(8, Date.valueOf(fromDate));
                statement.setDate(9, Date.valueOf(toDate));
                statement.setDate(10, Date.valueOf(fromDate));
                statement.setDate(11, Date.valueOf(toDate));
                try (ResultSet resultSet = statement.executeQuery()) {
                    List<ThongKeTonKhoDto> results = new ArrayList<>();
                    while (resultSet.next()) {
                        results.add(new ThongKeTonKhoDto(
                                resultSet.getString("MaThuoc"),
                                resultSet.getString("TenThuoc"),
                                resultSet.getString("DVT"),
                                resultSet.getInt("TonDauKy"),
                                resultSet.getInt("NhapTrongKy"),
                                resultSet.getInt("XuatTrongKy"),
                                resultSet.getInt("TonCuoiKy")
                        ));
                    }
                    return results;
                }
            }
        } catch (Exception exception) {
            throw new IllegalStateException("Could not query XNT report.", exception);
        } finally {
            closeConnection(connection);
        }
    }

