    private List<ThongKeTopSanPhamDto> queryTopProducts(String sql, DateRangeRequest request, int limit) {
        Connection connection = null;
        try {
            connection = getConnection();
            try (PreparedStatement statement = connection.prepareStatement(sql)) {
                statement.setDate(1, Date.valueOf(request.getFromDate()));
                statement.setDate(2, Date.valueOf(request.getToDate()));
                statement.setInt(3, limit);
                try (ResultSet resultSet = statement.executeQuery()) {
                    List<ThongKeTopSanPhamDto> results = new ArrayList<>();
